pub fn t(key: &str, args: &[(&str, &str)]) -> String {
    let template = EN
        .iter()
        .chain(crate::messages_tunnel::EN.iter())
        .chain(crate::messages_v1::EN.iter())
        .chain(crate::messages_backup::EN.iter())
        .chain(crate::messages_models::EN.iter())
        .chain(crate::messages_code::EN.iter())
        .chain(crate::messages_sched::EN.iter())
        .chain(crate::messages_runs::EN.iter())
        .chain(crate::messages_perm::EN.iter())
        .chain(crate::messages_cost::EN.iter())
        .chain(crate::messages_alerts::EN.iter())
        .chain(crate::messages_secrets::EN.iter())
        .chain(crate::messages_orch::EN.iter())
        .chain(crate::messages_agent::EN.iter())
        .chain(crate::messages_chat::EN.iter())
        .chain(crate::messages_hardening::EN.iter())
        .chain(crate::messages_infra::EN.iter())
        .chain(crate::messages_adopt_key::EN.iter())
        .chain(crate::messages_quiesce::EN.iter())
        .find(|(k, _)| *k == key)
        .map(|(_, v)| (*v).to_string())
        .unwrap_or_else(|| key.to_string());
    // One pass: a value that itself holds `{name}` is never filled in by a later argument.
    let mut out = String::with_capacity(template.len());
    let mut rest = template.as_str();
    while let Some(i) = rest.find('{') {
        out.push_str(&rest[..i]);
        let after = &rest[i + 1..];
        if let Some(j) = after.find('}') {
            if let Some((_, v)) = args.iter().find(|(n, _)| *n == &after[..j]) {
                out.push_str(v);
                rest = &after[j + 1..];
                continue;
            }
        }
        out.push('{');
        rest = after;
    }
    out.push_str(rest);
    out
}

#[cfg(test)]
pub fn keys() -> Vec<&'static str> {
    EN.iter()
        .chain(crate::messages_tunnel::EN.iter())
        .chain(crate::messages_code::EN.iter())
        .chain(crate::messages_alerts::EN.iter())
        .chain(crate::messages_cost::EN.iter())
        .map(|(k, _)| *k)
        .collect()
}
